ee:variables.ee:set-variable:
%dw 2.0
output application/xml
ns ns0 http://tempuri.org/
ns ns01 http://www.etb.com.co/orquestador
ns ns02 http://schemas.datacontract.org/2004/07/Orquestador.Contracts.Solicitudes
---
{
	ns0#RestaurarProcesoOrden: {
		ns0#solicitudOrden: {
			ns01#Encabezado: {
				ns01#Sistema: {
					ns01#IdCorrelacion: vars.orderNumber,
					ns01#Nombre: p('orquestador.tecnologia'),
					ns01#Servidor: p('orquestador.servidor')
				}
			},
			ns02#DatosSolicitud: {
				ns01#NumeroOrden: vars.orderNumber,
                ns01#Proceso: true,
                ns01#EjecutarProceso: true,
                ns01#IdServicio: vars.orderData[0].Orden_Activacion.Servicios.Id_Servicio,
                ns01#ContinuarServicio: false,
				ns01#Orquestar: true
			}
		}
	}
}

%dw 2.0
output application/xml
ns ns0 http://tempuri.org/
ns ns01 http://www.etb.com.co/orquestador
---
{
	ns0#ProcesarOrden: {
		ns0#solicitudOrden: {
			ns01#Encabezado: {
				ns01#Propiedades: {
					ns01#Propiedad: {
						ns01#Nombre: "",
						ns01#Valor: ""
					}
				},
				ns01#Sistema: {
					ns01#IdCorrelacion: vars.orderNumber,
					ns01#Nombre: p('orquestador.tecnologia'),
					ns01#Servidor: p('orquestador.servidor')
				}
			},
			ns01#DatosSolicitud: {
				ns01#EstadoOrden: vars.estadoOrden,
				ns01#NumeroOrden: vars.orderNumber,
				ns01#Tramite: vars.orderData[0].Tramite.'Tipo_Tramite', //vars.tipoTramite,
				ns01#UsuarioEvento: ""
			}
		}
	}
}

ee:message.ee:set-payload:
%dw 2.0
output application/json
var statusEncabezado = vars.orquestadorProvisioningResponse.Resultado.Encabezado.Servicio.Estado
var detalleEncabezado = vars.orquestadorProvisioningResponse.Resultado.Encabezado.Servicio.DetalleEstado
var status = vars.orquestadorProvisioningResponse.Resultado.Estado.Codigo default ""
var detalle = vars.orquestadorProvisioningResponse.Resultado.Estado.Descripcion default ""
var fechaActivacion = vars.orquestadorProvisioningResponse.Resultado.Estado.Fecha default ""
---
if(statusEncabezado == "OK")
{
  "status": status,
  "orderNumber": vars.orderNumber,
  "description": if (vars.orderData[0].Orden_Activacion.Estado_Orden.Codigo == '35') vars.orderData[0].Orden_Activacion.Comandos_Ejecutados[-1].primaryKey else detalle,
  "serviceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio", //vars.serviceAccount,
  "activationDate": fechaActivacion
}
else
{
  "status": 500,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": detalleEncabezado
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

%dw 2.0
output application/json
var statusEncabezado = vars.orquestadorProvisioningResponse.Resultado.Encabezado.Servicio.Estado
var detalleEncabezado = vars.orquestadorProvisioningResponse.Resultado.Encabezado.Servicio.DetalleEstado
var status = vars.orquestadorProvisioningResponse.Resultado.Estado.Codigo default ""
var detalle = vars.orquestadorProvisioningResponse.Resultado.Estado.Descripcion default ""
var fechaActivacion = vars.orquestadorProvisioningResponse.Resultado.Estado.Fecha default ""
---
if(statusEncabezado == "OK")
{
  "status": status,
  "orderNumber": vars.orderNumber,
  "description": detalle,
  "serviceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio", //vars.serviceAccount,
  "activationDate": fechaActivacion
}
else
{
  "status": 500,
  "code": "INTERNAL_SERVER_ERROR",
  "message": {
    "message": detalleEncabezado
  },
  "messageServer": "",
  "cause": [
    {
      "origin": app.name,
      "message": "org.mule.extension.http.api.request.validator.ResponseValidatorTypedException"
    }
  ]
}

%dw 2.0
output application/json
---
{
  "status": vars.ordenComercial,
  "orderNumber": vars.orderNumber,
  "description": vars.orderData[0].Estado_Orden_Comercial.Descripcion,
  "serviceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio", //vars.serviceAccount,
  "activationDate": (now() >> "America/Bogota") as String {format : p('format-date')}
}

%dw 2.0
output application/json
---
{
  "status": vars.ordenComercial,
  "orderNumber": vars.orderNumber,
  "description": vars.orderData[0].Orden_Activacion.Comandos_Ejecutados[-1].primaryKey,
  "serviceAccount": vars.orderData[0]."Servicio_Tramite"."Id_Cuenta_Servicio", //vars.serviceAccount,
  "activationDate": (now() >> "America/Bogota") as String {format : p('format-date')}
}
